"""Composition advice afterassignment and40+minute gold-weight display."""
import json
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parent
report={'errors':[],'checks':[]}
def load(q,s):q.evaluate("s=>sessionStorage.setItem('_qa_next_save',JSON.stringify(s))",s);q.reload(wait_until='domcontentloaded')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);q=b.new_page(viewport={'width':1440,'height':1100});q.set_default_timeout(25000);q.on('pageerror',lambda e:report['errors'].append(str(e)));q.add_init_script("const s=sessionStorage.getItem('_qa_next_save');if(s){localStorage.setItem('lck-manager-save-v1',s);sessionStorage.removeItem('_qa_next_save');}");q.goto('http://127.0.0.1:4173');q.locator('[data-action=new-game]').click()
 fixture=q.evaluate("""async()=>{const E=await import('./engine.js'),s=E.newGame('T1',44),m={id:'2026-composition-qa',phase:'CUP_FINAL',competition:'CUP',bestOf:5,date:s.date,teams:['T1','GEN'],sets:[],score:[0,0],status:'scheduled'};s.matches.push(m);const d=E.newDraft(s,m,'both:blue:first'),chosen={blue:['Ornn','Sejuani','Orianna','Jinx','Lulu'],red:['Renekton','Elise','Leblanc','Lucian','Pyke']};while(E.draftTurn(d)){const t=E.draftTurn(d),id=t.kind==='pick'?chosen[t.side].find(id=>!d.picks[t.side].some(p=>p.champion===id)):E.legalChampions(s,d).find(c=>!Object.values(chosen).flat().includes(c.id)).id;E.draftAction(s,d,id);}E.prepareAssignments(s,d);s.activeDraft=d;return s;}""")
 load(q,fixture);q.locator('.assignment-room').wait_for();q.locator('[data-action=assignment-pause]').click();assert q.locator('.composition-pending').count()==1;q.locator('[data-action=assignment-auto]').click();q.locator('.composition-report').wait_for();text=q.locator('.composition-report').inner_text();assert '20분' in text and '45분' in text and '딜러 보호' in text and '피해 유형' in text;q.screenshot(path=str(ROOT/'2026-composition-advice.png'),full_page=True);q.reload();q.locator('.composition-report').wait_for();assert q.locator('.composition-report').inner_text()==text;report['checks'].append('assignedchampionsgetrole-awarecompositionadvice,20vs45minuteestimates,andreloadstability')
 late=q.evaluate("""async()=>{const E=await import('./engine.js');for(let seed=1;seed<=200;seed++){const s=E.newGame('T1',seed),m={id:'2026-lategame-qa',phase:'CUP_GROUP',competition:'CUP',bestOf:1,date:s.date,teams:['T1','GEN'],sets:[],score:[0,0],status:'scheduled'};s.matches.push(m);const d=E.completeDraft(s,E.newDraft(s,m));E.autoAssignDraft(s,d);E.confirmDraftAssignments(d);const set=E.resolveDraft(s,m,d),index=set.events.findIndex(e=>e.minute>=42&&Number.isFinite(e.goldWeight));if(index>=0){s.viewing={matchId:m.id,setIndex:0};return{state:s,set,index,seed};}}throw Error('No lategamefixture');}""")
 load(q,late['state']);q.locator('.vct-shell').wait_for();q.locator('[data-action=menu]').click();q.locator('.vct-quick-menu [data-id=history]').click();q.locator('[data-action=match-record][data-id="2026-lategame-qa"]').click();q.locator('.rift-svg').wait_for();q.locator('[data-action=viewer-speed][data-speed="8"]').click();q.locator(f'[data-action=viewer-scene][data-index="{late["index"]}"]').click();q.wait_for_function("document.querySelector('#live-battle-context')?.textContent.includes('장기전')");expected=round(late['set']['events'][late['index']]['goldWeight']*100);assert f'골드 영향 {expected}%' in q.locator('#live-battle-context').inner_text();q.wait_for_function("document.querySelector('[data-action=viewer-play]').textContent==='재생'");q.wait_for_timeout(100);q.screenshot(path=str(ROOT/'2026-gold-late-fight.png'),full_page=True);assert not report['errors'],report['errors'];report['checks'].append('event-v4savedlategamematchshowstime-decayedgoldweightandcompositioncontext');report['lateGameExample']={'seed':late['seed'],'minute':late['set']['events'][late['index']]['minute'],'goldWeight':late['set']['events'][late['index']]['goldWeight'],'model':late['set']['simulationReplay']['model']};(ROOT/'gold-composition-browser-results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False));b.close()
